import 'package:flutter/material.dart';
import '../core/types.dart';
import '../core/store.dart';
import '../core/calculations.dart';
import '../shared/ui.dart';

Widget simpleList(BuildContext context,LocalStore store,String kind,String title,List<FieldSpec> specs,{String? notice})=>RecordList(title:title,kind:kind,store:store,subtitle:(r)=>str(r['notes']),edit:(r)async{await openPage(context,GenericEditor(title:title,kind:kind,initial:r??{},store:store,fields:specs,notice:notice));});
Widget gradesPage(BuildContext context,LocalStore store)=>simpleList(context,store,'grade','Fleischgüteklassen',const [FieldSpec('name','Bezeichnung / Sortierung',required:true),FieldSpec('description','Beschreibung',multiline:true),FieldSpec('notes','Eigene Qualitätsanforderungen',multiline:true)],notice:'Eigene betriebliche Fleischsortierungen hinterlegen. Keine voreingestellten fachlichen Grenzwerte.');
Widget suppliersPage(BuildContext context,LocalStore store)=>simpleList(context,store,'supplier','Lieferanten',const [FieldSpec('name','Name',required:true),FieldSpec('contact','Kontakt'),FieldSpec('address','Adresse',multiline:true),FieldSpec('notes','Notizen',multiline:true)]);
Widget materialsPage(BuildContext context,LocalStore store,bool meat)=>RecordList(title:meat?'Fleischverwaltung':'Zutaten & Gewürze',kind:meat?'meat':'ingredient',store:store,subtitle:(r)=>'${meat?'${str(r['animal'])} · ${str(r['grade'])}':str(r['category'])} · ${shownMoney(r['buyPrice'])} / ${shownNum(r['buyQuantity'],digits:3)} ${str(r['buyUnit'])}',edit:(r)async{await openPage(context,MaterialEditor(store:store,meat:meat,initial:r));});
class MaterialEditor extends StatefulWidget{
  final LocalStore store;final bool meat;final Json? initial;
  const MaterialEditor({super.key,required this.store,required this.meat,this.initial});
  @override State<MaterialEditor> createState()=>_MaterialEditorState();
}
class _MaterialEditorState extends State<MaterialEditor>{
  final form=GlobalKey<FormState>();late Json data={if(widget.initial==null)...{'buyQuantity':1.0,'buyUnit':widget.meat?'kg':'g','food':true},...?widget.initial};late Json analysis=map(data['analysis']);bool busy=false;
  void changed()=>setState((){});
  Future<void> save()async{if(busy||!(form.currentState?.validate()??false))return;setState(()=>busy=true);await guarded(context,()async{await widget.store.save(widget.meat?'meat':'ingredient',{...data,'analysis':analysis,'food':widget.meat||data['food']==true});if(mounted)Navigator.pop(context,true);});if(mounted)setState(()=>busy=false);}
  @override Widget build(BuildContext context){final price=numOrNull(data['buyPrice']);final q=numOrNull(data['buyQuantity']);final unit=str(data['buyUnit']);final target=widget.meat?'kg':unit;final per=q!=null&&q>0&&price!=null?convert(1,target,unit):null;final history=widget.store.all('priceHistory').where((r)=>r['materialId']==data['id']).toList()..sort((a,b)=>str(b['created']).compareTo(str(a['created'])));
    return PageFrame(title:widget.meat?'Fleisch bearbeiten':'Zutat bearbeiten',child:Form(key:form,child:ListView(padding:const EdgeInsets.all(12),children:[Section('Stammdaten',[Fields(specs:[const FieldSpec('name','Bezeichnung',required:true),if(widget.meat)...[FieldSpec('animal','Tierart',choices:widget.store.animalTypes,required:true),FieldSpec('grade','Güteklasse / Sortierung',choices:['Nicht zugeordnet',...widget.store.all('grade').map(nameOf)],required:true),const FieldSpec('origin','Herkunft') ]else...[const FieldSpec('category','Kategorie',choices:ingredientCategories,required:true),const FieldSpec('food','Geht in die essbare Rohmasse ein',check:true,hint:'Für Hüllen/Verpackung nach tatsächlicher Verwendung einstellen.')],FieldSpec('supplier','Lieferant',choices:['Nicht zugeordnet',...widget.store.all('supplier').map(nameOf)]),const FieldSpec('notes','Notizen',multiline:true)],data:data,changed:changed)]),Section('Einkaufspreis (netto / Kostenbasis)',[Fields(specs:[const FieldSpec('buyQuantity','Einkaufsmenge',required:true,number:true,min:0.000001),FieldSpec('buyUnit','Einheit',choices:widget.meat?const ['kg','g']:units,required:true),const FieldSpec('buyPrice','Einkaufspreis gesamt (€)',required:true,number:true,min:0)],data:data,changed:changed),ValueRow('Preis pro $target',per==null?'–': '${fmt(price!*per/q!,4)} €',strong:true),for(final u in compatibleUnits(unit).where((u)=>u!=target))ValueRow('Preis pro $u',price==null||q==null||q<=0?'–':'${fmt(price*convert(1,u,unit)!/q,6)} €')]),Section('Qualität und Deklaration',[const Notice('Werte je kg Rohstoff bzw. in Masse-%. Unbekannte Werte leer lassen, bestätigte Null explizit eingeben. Keine Laboranalyse wird ersetzt.'),Fields(specs:[for(final key in [...rawMetrics,'beffe'])FieldSpec(key,'${qualityMetrics[key]} (${metricUnit(key)})',number:true,min:0,max:metricUnit(key)=='%'?100:null)],data:analysis,changed:changed),Fields(specs:const [FieldSpec('analysisSource','Quelle der Analysewerte',choices:['Schätzung','Herstellerangabe','Messung','Labor']),FieldSpec('analysisReference','Fundstelle / Laborbericht / Datum',multiline:true),FieldSpec('allergens','Allergene laut Spezifikation',multiline:true),FieldSpec('additives','Zusatzstoffe / E-Nummern / Konzentrationen',multiline:true)],data:data,changed:changed)]),if(history.isNotEmpty)Section('Preisverlauf',[for(final h in history)ValueRow(dateLabel(h['created']),'${shownMoney(h['buyPrice'])} / ${shownNum(h['buyQuantity'])} ${str(h['buyUnit'])}')]),FilledButton.icon(onPressed:busy?null:save,icon:const Icon(Icons.save),label:const Text('Speichern')),const SizedBox(height:24)])));}
}
